import{_ as a,o as e,c as n,a3 as h}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"正易心法","description":"宋·麻衣道者撰、陈抟注的《正易心法》——主张舍辞求画、直追羲皇，以卦画本身（阴阳、血气、卦脉）说《易》，是象数一派的重要文献。","frontmatter":{"title":"正易心法","description":"宋·麻衣道者撰、陈抟注的《正易心法》——主张舍辞求画、直追羲皇，以卦画本身（阴阳、血气、卦脉）说《易》，是象数一派的重要文献。","category":"guide","aliases":["正易心法","麻衣道者","zheng yi xin fa"],"source":["《正易心法》"]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/index.md","filePath":"yijing/zheng-yi-xin-fa/index.md","lastUpdated":1790647676000}'),r={name:"yijing/zheng-yi-xin-fa/index.md"};function l(t,i,p,g,o,f){return e(),n("div",null,[...i[0]||(i[0]=[h('<h1 id="正易心法" tabindex="-1">正易心法 <a class="header-anchor" href="#正易心法" aria-label="Permalink to &quot;正易心法&quot;">​</a></h1><p>《正易心法》一卷，题为宋·麻衣道者撰、陈抟（希夷先生）注。全书正文四十二章，另有前序（陈抟传记）与后序、跋。</p><p>它的主张很鲜明：<strong>《易》的本意在卦画，不在文字</strong>。周文王的卦辞、周公的爻辞、孔子十翼，都是「不得已而有辞」的补救；读者若只停在辞上，就成了「买椟还珠」。</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>这是一部<strong>象数派</strong>的易学短著，四十余章各讲一个要点：卦画实义、阴阳运动、反对与对体、取象与名义、爻数与闰数、大衍与揲法、五行生成之数，末章归结为「当于羲皇心地驰骋，无于周孔言语下拘挛」。</p><table tabindex="0"><thead><tr><th>部分</th><th>内容</th></tr></thead><tbody><tr><td><strong>前序</strong></td><td>陈抟传记——为全书建立「象数真传、直追羲皇」的立场</td></tr><tr><td><strong>正文 42 章</strong></td><td>每章一段正文 + 麻衣注（陈抟述），逐章讲卦画之理</td></tr><tr><td><strong>后序</strong></td><td>李潜（几道）述此书来历与价值</td></tr><tr><td><strong>跋</strong></td><td>戴师愈述麻衣识人之明</td></tr></tbody></table><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><ul><li>它是理解**「象数」与「义理」分野**的一个极好入口：书中直说「《易》道不传，乃有周、孔。周、孔孤行，《易》道复晦」。</li><li>它把卦画讲成<strong>一套流动的结构</strong>：一卦之中具八卦、一卦有八变、反对与对体的分别、爻数与闰数的对应。</li><li>南宋朱熹曾力辨此书为伪托，真伪之争本身也是易学史的一段公案。</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先读<strong>前序</strong>——知道这套易学从哪里来；</li><li>再读正文，<strong>一章一章读</strong>：每章都是「一句总纲 + 一段注」；</li><li>遇到与十翼说法不同的地方，不必急着判对错——两存之，正可看出象数与义理的差异；</li><li>末章（第四十二）是全书收束，可与第一章对读。</li></ol><h2 id="篇章" tabindex="-1">篇章 <a class="header-anchor" href="#篇章" aria-label="Permalink to &quot;篇章&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/preface">前序 · 陈抟传记</a> — 神异出身、四拒帝王、传法两线</li></ul><p><strong>正文四十二章</strong></p><ul><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-01">第一章 · 羲皇《易》道，包括万象</a> — 「落处」：卦画即自然之象</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-02">第二章 · 六画之设，非是曲意</a> — 阴阳运动（十二消息卦）与血气流行（脏腑配数）</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-03">第三章 · 卦象视人，本无文字</a> — 羲皇不立文字，使人嘿观；不言之教</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-04">第四章 · 《易》道不传，乃有周孔</a> — 买椟还珠：执辞忘象，道复晦</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-05">第五章 · 无穷妙义，尽在画中</a> — 取次于艮坤：卦序长出来的，不是排出来的</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-06">第六章 · 消息卦画，无止于辞</a> — 辞外见意：辞是截面，画是全体</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-07">第七章 · 天地万物，理有未明</a> — 观于卦脉：坎离艮兑推知月日山雨，卦画如浑仪</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-08">第八章 · 经卦重卦，或离或合</a> — 纵横施设：六种读卦维度的总纲</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-09">第九章 · 乾坤错杂，乃生六子</a> — 破体：入位决定卦性</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-10">第十章 · 粤乾与坤，即是阴阳</a> — 纯而不驳：乾坤即是阴阳，圣贤各尽一道</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-11">第十一章 · 至于六子，即是阴阳</a> — 偏陂反侧：六子象众人万物，破体炼之纯体乃成</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-12">第十二章 · 健顺动入，陷丽止说</a> — 八字是结构原则，不是专属标签</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-13">第十三章 · 坎兑二水，明须识破</a> — 坎为乾水（气之液）、兑为坤水（形之散）</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-14">第十四章 · 钻木凿井，人之坎离</a> — 坎离为日月之体，日月交错生诸卦；穷理尽性</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-15">第十五章 · 八卦不止，天地雷风</a> — 凡健皆乾：八卦统摄万物，一身一物便具八卦</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-16">第十六章 · 卦有反对，最为关键</a> — 吉凶一体，对体八卦为造化枢机</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-17">第十七章 · 六十四卦，皆有取象</a> — 名义无不反对；不知取象是大病</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-18">第十八章 · 诸卦名义，须究端的</a> — 二十二卦名义：师比汤武、同人大有舜禹</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-19">第十九章 · 一卦之中，凡具八卦</a> — 正伏互参＋八变：读卦技术的顶点</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-20">第二十章 · 六十四卦，唯乾与坤</a> — 真体：本之自然、无所假合、纯一不驳、倒正不变</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-21">第二十一章 · 六子重卦，乾坤杂气</a> — 假合：分而散之则无有定体</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-22">第二十二章 · 卦义未审，须求变复</a> — 变复：义实通明</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-23">第二十三章 · 古今传易，舛讹为多</a> — 文献批评：履畜之序与八体正误</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-24">第二十四章 · 画卦取象，本为特物</a> — 见于日用：行止坐卧皆《易》，百姓罔觉</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-25">第二十五章 · 中爻之义，足为造化</a> — 参互成卦：纳音、反切、卦体其理则一</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-26">第二十六章 · 反对正如，甲子乙丑</a> — 有本有余：卦序相次皆余气</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-27">第二十七章 · 每卦之体，六画便具</a> — 六虚：六画乃天地四方之象</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-28">第二十八章 · 乾坤六子，其象与数</a> — 乾坤在外，六子包于其中</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-29">第二十九章 · 爻数三百八十又四</a> — 以闰求之，其数吻合</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-30">第三十章 · 二十四爻，求之八卦</a> — 画纯为叠，是为闰数</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-31">第三十一章 · 一岁之数，三百六十</a> — 八卦八变，气数已尽</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-32">第三十二章 · 数成于三，重之则六</a> — 进数退数：三画六画之由</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-33">第三十三章 · 凡物之数，有进有退</a> — 盛衰之数相半，进以此数退以此数</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-34">第三十四章 · 凡具于形，便具五数</a> — 气圆形方，五数既具十数乃成</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-35">第三十五章 · 大衍七七，其一不用</a> — 一者数之宗本，理自不动</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-36">第三十六章 · 策数六八，八卦定数</a> — 五十、四十九、四十八：筮法操作章</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-37">第三十七章 · 五行之数，须究落处</a> — 成象成形；先天与《太玄》之倍数</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-38">第三十八章 · 卦位生数，运以成数</a> — 生数成数：天地交感，感应之道</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-39">第三十九章 · 一变为七，七变为九</a> — 归魂复变；解第三十六章悬案</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-40">第四十章 · 名易之义，非训变易</a> — 大易未见气；易是什么</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-41">第四十一章 · 《易》道弥漫，九流可入</a> — 活法自悟：于羲皇心地上驰骋</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-42">第四十二章 · 世俗学解，浸渍旧闻</a> — 借辞以明画象；呜乎</p></li><li><p><a href="/Dao/yijing/zheng-yi-xin-fa/postscript">后序与跋</a> — 李潜「读书十年方悟」；戴师愈「三天子气」</p></li></ul><blockquote><p>全书正文四十二章与后序、跋，已全部整理完毕。</p></blockquote><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/">易经总览</a></li><li><a href="/Dao/yijing/shi-yi/">十翼总览</a> — 本书对「周、孔之辞」的批评，正需与十翼对读</li><li><a href="/Dao/yijing/yi-li/">义理总览</a> — 义理派与象数派的分野</li><li><a href="/Dao/yijing/meihua-yishu/">梅花易数</a> — 同属象数一路</li></ul>',17)])])}const x=a(r,[["render",l]]);export{c as __pageData,x as default};
